// High school intro psychology quizzes — hb01 through hb15
export const HS_PSYCHOLOGY_QUIZZES = [
  { id:'hb01', cat:'Behavioral & Social Sciences', title:`What Is Psychology? Intro & Perspectives`, diff:'Easy', qs:[
      { q:`Psychology is best defined as the scientific study of:`, ch:[`The brain only`,`Behavior and mental processes`,`Mental illness only`,`Human relationships only`], ans:1, exp:`Psychology studies both behavior (what people do) and mental processes (thoughts, feelings) using scientific methods.` },
      { q:`Which perspective in psychology focuses on how our thoughts influence behavior?`, ch:[`Biological perspective`,`Cognitive perspective`,`Behavioral perspective`,`Psychodynamic perspective`], ans:1, exp:`The cognitive perspective looks at how mental processes like thinking, memory, and problem-solving shape behavior.` },
      { q:`A psychologist who studies how hormones and brain chemistry affect mood is working from which perspective?`, ch:[`Behavioral`,`Humanistic`,`Biological`,`Sociocultural`], ans:2, exp:`The biological perspective examines how the brain, nervous system, and hormones influence behavior and mental processes.` },
      { q:`Sigmund Freud is most closely associated with which perspective in psychology?`, ch:[`Behavioral perspective`,`Psychodynamic perspective`,`Humanistic perspective`,`Cognitive perspective`], ans:1, exp:`Freud founded the psychodynamic perspective, which emphasizes unconscious thoughts and childhood experiences.` },
      { q:`The behavioral perspective focuses mainly on:`, ch:[`Unconscious desires`,`Observable behavior and how it is learned`,`Self-actualization and personal growth`,`Brain structures`], ans:1, exp:`Behaviorists like John Watson and B.F. Skinner focused on studying behavior that can be directly observed and measured.` },
      { q:`Which perspective emphasizes personal growth, free will, and reaching one's full potential?`, ch:[`Humanistic perspective`,`Behavioral perspective`,`Biological perspective`,`Psychodynamic perspective`], ans:0, exp:`The humanistic perspective, associated with psychologists like Carl Rogers and Abraham Maslow, stresses free will and personal growth.` },
      { q:`Wilhelm Wundt is often credited as a founder of psychology because he:`, ch:[`Invented the first personality test`,`Opened the first psychology research lab`,`Discovered the neuron`,`Created the first IQ test`], ans:1, exp:`Wundt opened the first formal psychology laboratory in Germany in 1879, marking psychology's start as a science.` },
      { q:`A clinical psychologist is someone who:`, ch:[`Only studies animal behavior`,`Helps diagnose and treat mental and emotional problems`,`Only conducts brain surgery`,`Teaches high school science`], ans:1, exp:`Clinical psychologists assess and help treat people dealing with mental health and emotional difficulties.` },
      { q:`Which of these is an example of a "mental process" rather than a "behavior"?`, ch:[`Waving hello`,`Solving a math problem in your head`,`Running a race`,`Writing a letter`], ans:1, exp:`Mental processes are internal, like thinking or feeling, while behaviors are actions others can observe.` },
      { q:`Which sub-field of psychology focuses specifically on how the workplace affects employees?`, ch:[`Developmental psychology`,`Industrial-organizational psychology`,`Clinical psychology`,`Forensic psychology`], ans:1, exp:`Industrial-organizational psychologists study behavior and performance in workplace settings.` },
      { q:`The nature vs. nurture debate in psychology asks whether behavior is more influenced by:`, ch:[`Genetics vs. environment`,`Emotion vs. logic`,`Memory vs. perception`,`Conscious vs. unconscious thought`], ans:0, exp:`Nature refers to genetic/biological influences, while nurture refers to environmental and experiential influences on behavior.` },
      { q:`Why is psychology considered a science?`, ch:[`Because it only studies the brain`,`Because psychologists rely on personal opinions`,`Because it uses systematic, testable research methods to study behavior and mental processes`,`Because it never changes its theories`], ans:2, exp:`Psychology is a science because it uses careful observation, testing, and evidence rather than guesswork.` },
    ]
  },
  { id:'hb02', cat:'Behavioral & Social Sciences', title:`The Brain & Nervous System Basics`, diff:'Easy', qs:[
      { q:`The basic building block (cell) of the nervous system is called a:`, ch:[`Neuron`,`Synapse`,`Axon`,`Hormone`], ans:0, exp:`Neurons are specialized cells that send and receive messages throughout the nervous system.` },
      { q:`The tiny gap between two neurons where chemical messages are passed is called the:`, ch:[`Cerebellum`,`Synapse`,`Cortex`,`Dendrite`], ans:1, exp:`The synapse is the small space between neurons where neurotransmitters carry signals from one neuron to the next.` },
      { q:`Chemical messengers that carry signals across the synapse are called:`, ch:[`Hormones`,`Neurotransmitters`,`Enzymes`,`Antibodies`], ans:1, exp:`Neurotransmitters are chemicals released by neurons to send messages to other neurons or cells.` },
      { q:`Which part of the brain controls balance and coordination of movement?`, ch:[`Cerebellum`,`Frontal lobe`,`Hippocampus`,`Amygdala`], ans:0, exp:`The cerebellum, located at the back of the brain, helps coordinate balance and smooth muscle movement.` },
      { q:`The frontal lobe of the brain is most associated with:`, ch:[`Hearing`,`Decision-making and planning`,`Basic vision`,`Sense of smell`], ans:1, exp:`The frontal lobe handles higher-level thinking such as planning, decision-making, and impulse control.` },
      { q:`Which brain structure is often called the "memory center" because it helps form new memories?`, ch:[`Amygdala`,`Thalamus`,`Hippocampus`,`Medulla`], ans:2, exp:`The hippocampus plays a key role in forming and storing new long-term memories.` },
      { q:`The part of the nervous system made up of the brain and spinal cord is called the:`, ch:[`Peripheral nervous system`,`Central nervous system`,`Autonomic nervous system`,`Somatic nervous system`], ans:1, exp:`The central nervous system (CNS) consists of the brain and spinal cord, which process and send information.` },
      { q:`The "fight or flight" response is triggered mainly by which part of the nervous system?`, ch:[`Sympathetic nervous system`,`Parasympathetic nervous system`,`Central nervous system`,`Cerebellum`], ans:0, exp:`The sympathetic nervous system prepares the body for quick action during stress or danger, speeding up heart rate and breathing.` },
      { q:`Which brain structure is closely linked to processing fear and other strong emotions?`, ch:[`Amygdala`,`Cerebellum`,`Occipital lobe`,`Corpus callosum`], ans:0, exp:`The amygdala is a small brain structure that plays a major role in processing fear and emotional reactions.` },
      { q:`The occipital lobe of the brain is mainly responsible for processing:`, ch:[`Touch`,`Vision`,`Hearing`,`Taste`], ans:1, exp:`The occipital lobe, located at the back of the brain, is the brain's main center for processing visual information.` },
      { q:`Neurons send electrical signals down a long, thin part of the cell called the:`, ch:[`Dendrite`,`Axon`,`Synapse`,`Myelin sheath`], ans:1, exp:`The axon is the long fiber of a neuron that carries electrical signals away from the cell body toward other neurons.` },
      { q:`Damage to the left side of the brain often affects the right side of the body because:`, ch:[`The brain's two sides are unrelated to the body`,`Nerve pathways cross over between the brain and body`,`The right hemisphere controls hearing only`,`The spinal cord reverses signals randomly`], ans:1, exp:`Most nerve pathways cross sides between the brain and the body, so the left brain generally controls the right side of the body and vice versa.` },
    ]
  },
  { id:'hb03', cat:'Behavioral & Social Sciences', title:`Learning: Classical Conditioning Basics`, diff:'Easy', qs:[
      { q:`Classical conditioning is a type of learning in which:`, ch:[`Behavior is shaped by rewards and punishments`,`Two stimuli become linked so that one comes to trigger a response originally caused by the other`,`People learn by watching others`,`Learning happens only through trial and error`], ans:1, exp:`Classical conditioning links a neutral stimulus with a stimulus that already causes a reflex response, until the neutral stimulus alone triggers that response.` },
      { q:`In Pavlov's famous experiment, what was the unconditioned stimulus?`, ch:[`The bell`,`The food`,`The salivation`,`The dog`], ans:1, exp:`The food naturally caused the dogs to salivate without any learning, making it the unconditioned stimulus.` },
      { q:`In Pavlov's experiment, after training, the bell alone caused the dog to salivate. The bell is now called the:`, ch:[`Unconditioned stimulus`,`Unconditioned response`,`Conditioned stimulus`,`Neutral stimulus`], ans:2, exp:`Once the bell (originally neutral) triggers salivation on its own through learning, it becomes the conditioned stimulus.` },
      { q:`In classical conditioning, the learned response to the conditioned stimulus is called the:`, ch:[`Unconditioned response`,`Conditioned response`,`Neutral response`,`Reflex response`], ans:1, exp:`The conditioned response is the learned reaction (like salivating to a bell) that occurs after conditioning.` },
      { q:`Before conditioning begins, a stimulus that produces no particular response is called a:`, ch:[`Conditioned stimulus`,`Unconditioned stimulus`,`Neutral stimulus`,`Reinforcer`], ans:2, exp:`A neutral stimulus is something that initially causes no specific response, like the bell before it was paired with food.` },
      { q:`If a dog trained to salivate at a bell starts salivating at a similar buzzer sound too, this illustrates:`, ch:[`Extinction`,`Stimulus generalization`,`Spontaneous recovery`,`Discrimination`], ans:1, exp:`Stimulus generalization happens when a similar stimulus triggers the same conditioned response.` },
      { q:`If the bell is rung many times without ever being followed by food, and the dog eventually stops salivating to the bell, this is called:`, ch:[`Generalization`,`Discrimination`,`Extinction`,`Acquisition`], ans:2, exp:`Extinction occurs when the conditioned response fades because the conditioned stimulus is no longer paired with the unconditioned stimulus.` },
      { q:`A child who was once bitten by a dog and now feels afraid of all dogs is showing signs of:`, ch:[`Operant conditioning`,`Classical conditioning`,`Observational learning`,`Habituation`], ans:1, exp:`The child's fear response has become linked to dogs in general through classical conditioning of a fear association.` },
      { q:`John B. Watson's "Little Albert" experiment demonstrated that:`, ch:[`Fear can be learned through classical conditioning`,`Rewards increase behavior`,`Children learn language through imitation`,`Memory improves with repetition`], ans:0, exp:`Watson conditioned a baby named Albert to fear a white rat by pairing it with a loud, scary noise, showing that emotions can be classically conditioned.` },
      { q:`Which best describes taste aversion, a special case of classical conditioning?`, ch:[`Learning to like a food because of a reward`,`Developing a dislike for a food after it was followed by sickness, sometimes after just one pairing`,`Learning to eat healthy foods through repetition`,`Forgetting the taste of a food over time`], ans:1, exp:`Taste aversion can form quickly, even after a single pairing of a food with feeling sick, because it has survival value.` },
      { q:`In classical conditioning, timing matters most for which part of the process?`, ch:[`The conditioned stimulus must come well after the unconditioned stimulus`,`The neutral stimulus is typically presented shortly before the unconditioned stimulus`,`The unconditioned response never needs to occur`,`Only random pairings can work`], ans:1, exp:`Conditioning tends to work best when the neutral stimulus appears just before the unconditioned stimulus, so an association can form.` },
      { q:`Which of these is the best real-world example of classical conditioning?`, ch:[`A student studies harder after getting a good grade`,`A dog learns to sit for a treat`,`Hearing a specific song makes you instantly feel happy because you heard it often at a fun event`,`A child learns to tie their shoes by practicing`], ans:2, exp:`The song (originally neutral) became linked with positive feelings from the event, so now it triggers that feeling on its own.` },
    ]
  },
  { id:'hb04', cat:'Behavioral & Social Sciences', title:`Learning: Operant Conditioning Basics`, diff:'Easy', qs:[
      { q:`Operant conditioning is a type of learning where behavior is shaped mainly by:`, ch:[`Pairing two stimuli together`,`Its consequences, such as rewards and punishments`,`Watching and imitating others`,`Genetic instincts`], ans:1, exp:`In operant conditioning, behaviors that are followed by rewards tend to increase, while those followed by punishment tend to decrease.` },
      { q:`B.F. Skinner is best known for his research on:`, ch:[`Classical conditioning`,`Operant conditioning`,`Cognitive development`,`Personality traits`], ans:1, exp:`Skinner studied how consequences like rewards and punishments shape behavior, a process he called operant conditioning.` },
      { q:`Reinforcement in operant conditioning is any consequence that:`, ch:[`Decreases the likelihood of a behavior`,`Increases the likelihood of a behavior`,`Has no effect on behavior`,`Always involves physical punishment`], ans:1, exp:`Reinforcement makes a behavior more likely to happen again in the future.` },
      { q:`Giving a dog a treat every time it sits is an example of:`, ch:[`Positive punishment`,`Negative reinforcement`,`Positive reinforcement`,`Negative punishment`], ans:2, exp:`Positive reinforcement means adding a pleasant reward to increase a behavior, like giving a treat for sitting.` },
      { q:`A teenager cleans their room to stop their parent from nagging them. This is an example of:`, ch:[`Positive reinforcement`,`Negative reinforcement`,`Positive punishment`,`Extinction`], ans:1, exp:`Negative reinforcement means removing something unpleasant (the nagging) to increase a behavior (cleaning).` },
      { q:`Taking away a teenager's phone after they broke curfew is an example of:`, ch:[`Positive reinforcement`,`Negative reinforcement`,`Negative punishment`,`Positive punishment`], ans:2, exp:`Negative punishment involves removing something desirable (the phone) to decrease unwanted behavior.` },
      { q:`Scolding a child immediately after they misbehave, in hopes they stop, is an example of:`, ch:[`Positive punishment`,`Negative punishment`,`Positive reinforcement`,`Negative reinforcement`], ans:0, exp:`Positive punishment means adding something unpleasant (the scolding) to decrease a behavior.` },
      { q:`A slot machine that pays out after an unpredictable number of pulls uses which reinforcement schedule?`, ch:[`Fixed ratio`,`Fixed interval`,`Variable ratio`,`Variable interval`], ans:2, exp:`Variable ratio schedules reward behavior after an unpredictable number of responses, which is why slot machines are so hard to stop playing.` },
      { q:`Getting paid every two weeks regardless of how much work is done in that time is an example of:`, ch:[`Fixed ratio schedule`,`Fixed interval schedule`,`Variable ratio schedule`,`Continuous reinforcement`], ans:1, exp:`A fixed interval schedule provides reinforcement after a set amount of time has passed.` },
      { q:`Shaping, in operant conditioning, refers to:`, ch:[`Punishing all incorrect behaviors immediately`,`Reinforcing successive steps that gradually get closer to a desired behavior`,`Removing all reinforcement at once`,`Teaching through observation only`], ans:1, exp:`Shaping rewards small steps that move closer and closer to the final target behavior.` },
      { q:`In operant conditioning, extinction occurs when:`, ch:[`A behavior is punished harshly`,`A previously reinforced behavior is no longer reinforced and gradually decreases`,`Two stimuli are paired together`,`A behavior becomes automatic`], ans:1, exp:`When reinforcement stops, a behavior that was once rewarded will typically fade away over time.` },
      { q:`Which of the following is generally considered the most effective way to encourage long-term positive behavior?`, ch:[`Punishment alone`,`Reinforcement of desired behavior`,`Ignoring all behavior`,`Random consequences`], ans:1, exp:`Reinforcing desired behavior tends to build lasting habits more effectively than punishment alone, which mainly suppresses unwanted behavior.` },
    ]
  },
  { id:'hb05', cat:'Behavioral & Social Sciences', title:`Memory Basics: Encoding, Storage & Retrieval`, diff:'Easy', qs:[
      { q:`The three basic processes of memory are:`, ch:[`Encoding, storage, and retrieval`,`Sensation, perception, and attention`,`Learning, forgetting, and remembering`,`Short-term, long-term, and working memory`], ans:0, exp:`Memory involves encoding (getting information in), storage (keeping it), and retrieval (getting it back out).` },
      { q:`Which type of memory holds a very brief impression of sensory information, like an image or sound, for a fraction of a second?`, ch:[`Long-term memory`,`Sensory memory`,`Working memory`,`Procedural memory`], ans:1, exp:`Sensory memory briefly holds raw sensory information, like a visual afterimage, before it fades or moves on for further processing.` },
      { q:`Short-term memory is limited mainly by:`, ch:[`How long information can be stored, which is unlimited`,`Both a short time span and a limited number of items it can hold`,`The type of information being processed`,`Only how much sleep a person gets`], ans:1, exp:`Short-term memory can typically hold a small number of items for a brief period unless the information is rehearsed.` },
      { q:`Repeating a phone number over and over to keep it in mind until you dial it is an example of:`, ch:[`Elaborative rehearsal`,`Maintenance rehearsal`,`Long-term storage`,`Chunking`], ans:1, exp:`Maintenance rehearsal is simply repeating information to keep it active in short-term memory.` },
      { q:`Grouping information into meaningful units, like remembering a phone number as three chunks instead of ten digits, is called:`, ch:[`Chunking`,`Encoding failure`,`Retrieval cue`,`Extinction`], ans:0, exp:`Chunking organizes information into smaller, manageable groups, making it easier to remember.` },
      { q:`Long-term memory for how to perform skills, like riding a bike, is called:`, ch:[`Episodic memory`,`Semantic memory`,`Procedural memory`,`Sensory memory`], ans:2, exp:`Procedural memory stores information about how to do things, such as physical skills and habits.` },
      { q:`Memory for general facts and knowledge about the world, like knowing that Paris is the capital of France, is called:`, ch:[`Episodic memory`,`Semantic memory`,`Procedural memory`,`Working memory`], ans:1, exp:`Semantic memory stores general facts and knowledge that are not tied to a specific personal experience.` },
      { q:`Memory for personal experiences and specific events in your life, like your last birthday party, is called:`, ch:[`Semantic memory`,`Procedural memory`,`Episodic memory`,`Sensory memory`], ans:2, exp:`Episodic memory holds personal experiences and events tied to a particular time and place.` },
      { q:`A helpful clue or reminder that helps trigger the retrieval of a stored memory is called a:`, ch:[`Retrieval cue`,`Sensory trace`,`Reinforcer`,`Neutral stimulus`], ans:0, exp:`A retrieval cue is any hint, such as a smell or a word, that helps bring a stored memory back to mind.` },
      { q:`Forgetting information because new information interferes with recalling older information is called:`, ch:[`Proactive interference`,`Retroactive interference`,`Encoding failure`,`Sensory decay`], ans:1, exp:`Retroactive interference happens when newly learned information makes it harder to remember information learned earlier.` },
      { q:`Forgetting a new locker combination because you keep remembering your old one instead is an example of:`, ch:[`Retroactive interference`,`Proactive interference`,`Chunking`,`Elaborative rehearsal`], ans:1, exp:`Proactive interference occurs when older memories interfere with learning or recalling newer information.` },
      { q:`Which strategy is generally most effective for moving information into long-term memory?`, ch:[`Simply repeating information without thinking about its meaning`,`Connecting new information to things you already know (elaborative rehearsal)`,`Reading information only once quickly`,`Avoiding sleep after studying`], ans:1, exp:`Elaborative rehearsal, which links new information to existing knowledge, tends to create stronger and more lasting memories than simple repetition.` },
    ]
  },
  { id:'hb06', cat:'Behavioral & Social Sciences', title:`States of Consciousness & Sleep Basics`, diff:'Easy', qs:[
      { q:`Consciousness in psychology refers to:`, ch:[`Only the state of being asleep`,`Your awareness of yourself and your surroundings`,`A permanent, unchanging state of mind`,`Only unconscious thoughts`], ans:1, exp:`Consciousness is a person's awareness of their own thoughts, feelings, and environment, and it can shift throughout the day.` },
      { q:`The stage of sleep associated with most vivid dreaming is called:`, ch:[`REM sleep`,`Stage 1 sleep`,`Deep sleep (slow-wave sleep)`,`Sleep paralysis`], ans:0, exp:`REM (rapid eye movement) sleep is the stage most closely linked with vivid dreaming.` },
      { q:`REM stands for:`, ch:[`Restful Energy Movement`,`Rapid Eye Movement`,`Regular Emotional Motion`,`Random Encoding Mechanism`], ans:1, exp:`REM stands for Rapid Eye Movement, referring to the quick eye movements that occur during this dream-heavy sleep stage.` },
      { q:`During which stage of sleep is it hardest to wake someone up?`, ch:[`Stage 1 (light sleep)`,`REM sleep`,`Deep sleep (slow-wave sleep)`,`The moment you first fall asleep`], ans:2, exp:`Deep sleep, also called slow-wave sleep, is the stage where people are typically hardest to wake up.` },
      { q:`Roughly how many hours of sleep do most teenagers need per night for healthy functioning?`, ch:[`3 to 4 hours`,`5 to 6 hours`,`8 to 10 hours`,`12 to 14 hours`], ans:2, exp:`Most teenagers need about 8 to 10 hours of sleep per night to support learning, mood, and overall health.` },
      { q:`The body's internal clock that regulates the sleep-wake cycle over about 24 hours is called the:`, ch:[`REM cycle`,`Circadian rhythm`,`Sensory adaptation cycle`,`Homeostatic drive`], ans:1, exp:`The circadian rhythm is the body's roughly 24-hour internal clock that helps regulate when we feel sleepy or alert.` },
      { q:`A person who has trouble falling or staying asleep on a regular basis may have a sleep disorder called:`, ch:[`Narcolepsy`,`Insomnia`,`Sleep apnea`,`Somnambulism`], ans:1, exp:`Insomnia is a common sleep disorder involving persistent difficulty falling asleep or staying asleep.` },
      { q:`A sleep disorder in which a person briefly and repeatedly stops breathing during sleep is called:`, ch:[`Insomnia`,`Narcolepsy`,`Sleep apnea`,`Night terrors`], ans:2, exp:`Sleep apnea involves repeated pauses in breathing during sleep, which can disrupt sleep quality.` },
      { q:`A sleep disorder that causes sudden, uncontrollable episodes of falling asleep during the day is called:`, ch:[`Narcolepsy`,`Insomnia`,`Sleep apnea`,`Sleepwalking`], ans:0, exp:`Narcolepsy causes sudden and uncontrollable sleep attacks, even during normal daytime activities.` },
      { q:`One well-supported reason we need sleep is that it helps with:`, ch:[`Permanently stopping brain activity`,`Consolidating memories and restoring the body`,`Preventing all dreaming`,`Eliminating the need for food`], ans:1, exp:`Sleep helps the brain consolidate memories from the day and allows the body to rest and repair itself.` },
      { q:`Which of the following is considered an altered state of consciousness?`, ch:[`Being wide awake and alert while reading`,`Daydreaming`,`Walking normally down the street`,`Solving a simple math problem while fully focused`], ans:1, exp:`Daydreaming is an altered state of consciousness because attention drifts away from the immediate environment.` },
      { q:`Caffeine is best classified as which type of drug based on its main effect on the nervous system?`, ch:[`Depressant`,`Stimulant`,`Hallucinogen`,`Opioid`], ans:1, exp:`Caffeine is a stimulant, meaning it increases alertness and activity in the nervous system.` },
    ]
  },
  { id:'hb07', cat:'Behavioral & Social Sciences', title:`Human Development Across the Lifespan (Intro)`, diff:'Easy', qs:[
      { q:`Developmental psychology is the study of:`, ch:[`Only childhood development`,`How people change physically, mentally, and socially across their entire lives`,`Only aging and the elderly`,`Only how memory develops`], ans:1, exp:`Developmental psychology looks at how people grow and change across the entire lifespan, from infancy to old age.` },
      { q:`A baby's ability to understand that an object still exists even when it can't be seen is called:`, ch:[`Object permanence`,`Conservation`,`Attachment`,`Egocentrism`], ans:0, exp:`Object permanence, described by Jean Piaget, is the understanding that objects continue to exist even when out of view.` },
      { q:`Jean Piaget is best known for his research on:`, ch:[`Personality traits`,`Stages of cognitive development in children`,`Sleep cycles`,`Social conformity`], ans:1, exp:`Piaget proposed a well-known theory describing stages children go through as their thinking abilities develop.` },
      { q:`The close emotional bond that forms between an infant and their primary caregiver is called:`, ch:[`Conservation`,`Attachment`,`Assimilation`,`Cognitive dissonance`], ans:1, exp:`Attachment is the emotional bond, usually with a parent or caregiver, that helps infants feel safe and secure.` },
      { q:`A securely attached infant, as described in attachment research, typically:`, ch:[`Avoids the caregiver entirely`,`Uses the caregiver as a safe base to explore and is easily comforted when upset`,`Shows no reaction when the caregiver leaves or returns`,`Only bonds with strangers`], ans:1, exp:`Securely attached infants feel comfortable exploring their environment because they trust their caregiver will be there for comfort.` },
      { q:`Adolescence is the developmental period best described as the transition between:`, ch:[`Infancy and early childhood`,`Childhood and adulthood`,`Middle age and old age`,`Prenatal development and infancy`], ans:1, exp:`Adolescence is the stage of development that bridges childhood and adulthood, often marked by puberty and identity exploration.` },
      { q:`According to Erik Erikson, a major task during adolescence is developing a clear sense of:`, ch:[`Trust in caregivers`,`Personal identity`,`Object permanence`,`Fine motor skills`], ans:1, exp:`Erikson described adolescence as a time when young people work to figure out who they are, which he called identity formation.` },
      { q:`Puberty refers to the period of development when:`, ch:[`Language skills first emerge`,`The body undergoes physical changes leading to sexual maturity`,`Object permanence first develops`,`A person retires from work`], ans:1, exp:`Puberty is the stage of physical development in which the body matures and becomes capable of reproduction.` },
      { q:`During infancy and early childhood, the type of play in which a child plays alongside others but not directly with them is called:`, ch:[`Cooperative play`,`Parallel play`,`Solitary play`,`Competitive play`], ans:1, exp:`Parallel play describes young children playing near each other with similar toys but not really interacting.` },
      { q:`Which of the following best describes physical development in older adulthood?`, ch:[`All cognitive and physical abilities decline equally and rapidly`,`Some physical and cognitive changes occur, but many abilities, especially accumulated knowledge, remain strong`,`No physical changes occur at all`,`Memory always improves with age`], ans:1, exp:`While some physical and cognitive changes happen with aging, many older adults retain strong knowledge and skills built over a lifetime.` },
      { q:`A key idea in developmental psychology is that development is shaped by both:`, ch:[`Genetics and environment`,`Only genetics`,`Only environment`,`Only parenting style`], ans:0, exp:`Most psychologists agree that both nature (genetics) and nurture (environment and experience) interact to shape development.` },
      { q:`Which term describes early, strong social and emotional connections that are important for healthy development in infancy?`, ch:[`Habituation`,`Bonding`,`Extinction`,`Conservation`], ans:1, exp:`Bonding refers to the early emotional connection that forms between infants and their caregivers, supporting healthy development.` },
    ]
  },
  { id:'hb08', cat:'Behavioral & Social Sciences', title:`Motivation & Emotion Basics`, diff:'Easy', qs:[
      { q:`Motivation refers to:`, ch:[`The process that directs and energizes behavior toward a goal`,`Only physical reflexes`,`A permanent personality trait`,`The way memories are stored`], ans:0, exp:`Motivation is what drives, directs, and sustains behavior aimed at reaching a goal.` },
      { q:`Abraham Maslow's hierarchy of needs is usually shown as a pyramid with which type of needs at the very bottom?`, ch:[`Self-actualization needs`,`Basic physiological needs, like food and water`,`Esteem needs`,`Belongingness needs`], ans:1, exp:`Maslow placed basic survival needs, such as food, water, and sleep, at the base of the pyramid since they must be met first.` },
      { q:`According to Maslow, self-actualization refers to:`, ch:[`Meeting basic survival needs`,`Reaching one's full potential and becoming the best version of oneself`,`Feeling a sense of belonging with others`,`Achieving safety and security`], ans:1, exp:`Self-actualization is at the top of Maslow's pyramid and represents the goal of fulfilling one's own personal potential.` },
      { q:`Motivation that comes from internal enjoyment or personal satisfaction, like reading a book because you love the story, is called:`, ch:[`Extrinsic motivation`,`Intrinsic motivation`,`Biological motivation`,`Social motivation`], ans:1, exp:`Intrinsic motivation comes from within, driven by personal interest or enjoyment rather than outside rewards.` },
      { q:`Motivation driven by outside rewards, like studying only to earn money from a parent, is called:`, ch:[`Intrinsic motivation`,`Extrinsic motivation`,`Instinctive motivation`,`Homeostatic motivation`], ans:1, exp:`Extrinsic motivation comes from external rewards or consequences rather than internal enjoyment.` },
      { q:`The body's tendency to maintain a stable internal environment, like regulating body temperature or hunger, is called:`, ch:[`Homeostasis`,`Attachment`,`Conservation`,`Cognitive dissonance`], ans:0, exp:`Homeostasis is the body's natural drive to keep internal conditions, like temperature and hunger, in balance.` },
      { q:`Emotions generally involve which three components?`, ch:[`Physical arousal, expressive behavior, and conscious experience/feeling`,`Only physical arousal`,`Only conscious thought`,`Only facial expression`], ans:0, exp:`Emotions typically combine a physical body response, an outward expression, and an inner subjective feeling.` },
      { q:`According to the James-Lange theory of emotion, which comes first?`, ch:[`The emotional feeling causes the physical response`,`The physical/bodily response happens first, and the emotion follows from noticing that response`,`Emotion and physical response happen at exactly the same time with no connection`,`Emotion occurs without any physical response`], ans:1, exp:`The James-Lange theory suggests we feel emotion after and because of noticing our body's physical reaction, such as feeling afraid because our heart is racing.` },
      { q:`Which of these is considered one of the basic, universally recognized human emotions studied by researchers like Paul Ekman?`, ch:[`Jealousy`,`Fear`,`Pride`,`Guilt`], ans:1, exp:`Fear is one of the basic emotions that research has found is expressed and recognized similarly across many cultures.` },
      { q:`Facial expressions for basic emotions, such as smiling when happy, tend to be:`, ch:[`Completely different across all cultures`,`Recognized similarly across many different cultures`,`Only learned in Western cultures`,`Impossible to interpret accurately`], ans:1, exp:`Research suggests that facial expressions for basic emotions like happiness and fear are recognized similarly around the world.` },
      { q:`Feeling "butterflies in your stomach" before a big test is an example of which part of an emotional response?`, ch:[`Cognitive appraisal`,`Physical/bodily arousal`,`Behavioral expression`,`Long-term memory`], ans:1, exp:`Physical sensations, like a fluttering stomach, are part of the body's physiological arousal during an emotional response.` },
      { q:`A student who studies hard mainly because they find the subject genuinely fascinating is showing:`, ch:[`Extrinsic motivation`,`Intrinsic motivation`,`Negative reinforcement`,`Classical conditioning`], ans:1, exp:`Studying out of genuine interest and enjoyment, rather than for an outside reward, reflects intrinsic motivation.` },
    ]
  },
  { id:'hb09', cat:'Behavioral & Social Sciences', title:`Personality Basics: Traits & the Big Five`, diff:'Easy', qs:[
      { q:`Personality can be defined as:`, ch:[`A person's temporary mood`,`A person's consistent patterns of thoughts, feelings, and behaviors over time`,`Only a person's physical appearance`,`A person's IQ score`], ans:1, exp:`Personality refers to the relatively stable and consistent ways a person thinks, feels, and behaves across different situations.` },
      { q:`Trait theories of personality generally focus on:`, ch:[`Identifying and measuring stable characteristics that describe individual differences`,`Only unconscious childhood conflicts`,`Only a person's environment`,`Predicting future behavior with 100% accuracy`], ans:0, exp:`Trait theories try to identify basic characteristics, like friendliness or organization, that remain fairly stable and differ between people.` },
      { q:`The Big Five personality model includes all of the following traits EXCEPT:`, ch:[`Openness`,`Conscientiousness`,`Intelligence`,`Neuroticism`], ans:2, exp:`Intelligence is not one of the Big Five traits; the five are openness, conscientiousness, extraversion, agreeableness, and neuroticism.` },
      { q:`In the Big Five model, "conscientiousness" refers to being:`, ch:[`Outgoing and energetic around others`,`Organized, responsible, and dependable`,`Curious and open to new experiences`,`Anxious and easily stressed`], ans:1, exp:`Conscientiousness describes how organized, careful, and dependable a person tends to be.` },
      { q:`In the Big Five model, "extraversion" describes a tendency to be:`, ch:[`Outgoing, energetic, and sociable`,`Anxious and emotionally unstable`,`Curious and imaginative`,`Kind and cooperative`], ans:0, exp:`Extraversion reflects how outgoing, talkative, and energized a person is by social interaction.` },
      { q:`In the Big Five model, "agreeableness" reflects how:`, ch:[`Organized a person is`,`Kind, cooperative, and warm a person tends to be toward others`,`Emotionally stable a person is`,`Curious a person is about new ideas`], ans:1, exp:`Agreeableness describes how compassionate, cooperative, and friendly someone tends to be with others.` },
      { q:`In the Big Five model, "neuroticism" describes a person's tendency toward:`, ch:[`Calmness and emotional stability`,`Anxiety, moodiness, and emotional instability`,`Curiosity and creativity`,`Organization and discipline`], ans:1, exp:`Neuroticism reflects how easily a person experiences negative emotions like anxiety, worry, or moodiness.` },
      { q:`In the Big Five model, "openness" refers to being:`, ch:[`Curious, imaginative, and open to new experiences`,`Shy and withdrawn`,`Highly organized and disciplined`,`Prone to negative emotions`], ans:0, exp:`Openness describes how curious, creative, and willing a person is to try new ideas and experiences.` },
      { q:`Sigmund Freud's psychodynamic theory of personality emphasized the importance of:`, ch:[`Observable behavior only`,`Unconscious thoughts and early childhood experiences`,`The Big Five traits`,`Genetics only`], ans:1, exp:`Freud believed personality was shaped largely by unconscious drives and experiences from early childhood.` },
      { q:`Humanistic psychologists, such as Carl Rogers, viewed personality development as driven mainly by:`, ch:[`Unconscious sexual conflicts`,`A natural drive toward personal growth and self-fulfillment`,`Random genetic mutations`,`Punishment and reward alone`], ans:1, exp:`Humanistic psychologists believed people have a natural tendency to grow, improve, and strive to reach their full potential.` },
      { q:`Which of the following is an example of a personality trait rather than a temporary state?`, ch:[`Feeling nervous right before a specific test`,`Being generally shy in most social situations`,`Being hungry after skipping lunch`,`Feeling tired after a late night`], ans:1, exp:`A trait is a stable, ongoing pattern like general shyness, unlike a temporary state such as feeling nervous or tired.` },
      { q:`Personality tests that ask people to rate themselves on a list of traits or statements are called:`, ch:[`Projective tests`,`Self-report inventories`,`IQ tests`,`Reflex tests`], ans:1, exp:`Self-report inventories ask individuals to answer questions about themselves, which researchers use to measure personality traits.` },
    ]
  },
  { id:'hb10', cat:'Behavioral & Social Sciences', title:`Stress & Coping Basics`, diff:'Easy', qs:[
      { q:`In psychology, stress is best defined as:`, ch:[`A permanent personality trait`,`The body and mind's response to demands or challenges that feel difficult to handle`,`A type of memory disorder`,`A pleasant emotional state only`], ans:1, exp:`Stress is the physical and mental response that occurs when we face demands or challenges we feel unable to easily manage.` },
      { q:`An event or situation that triggers stress, like an upcoming exam, is called a:`, ch:[`Stressor`,`Reinforcer`,`Neurotransmitter`,`Retrieval cue`], ans:0, exp:`A stressor is any event or situation that causes a stress response, such as a big test or an argument.` },
      { q:`The body's "fight or flight" stress response is activated by which part of the nervous system?`, ch:[`Sympathetic nervous system`,`Parasympathetic nervous system`,`Central nervous system only`,`Peripheral vision system`], ans:0, exp:`The sympathetic nervous system triggers the fight-or-flight response, preparing the body to react quickly to a stressor.` },
      { q:`Which hormone is commonly released by the body during stress and is often called the "stress hormone"?`, ch:[`Insulin`,`Cortisol`,`Melatonin`,`Dopamine`], ans:1, exp:`Cortisol is a hormone released during stress that helps the body respond to challenging or threatening situations.` },
      { q:`Coping strategies focused on directly solving the problem causing stress, like making a study plan before a test, are called:`, ch:[`Emotion-focused coping`,`Problem-focused coping`,`Avoidant coping`,`Classical conditioning`], ans:1, exp:`Problem-focused coping involves taking direct action to address and solve the source of stress.` },
      { q:`Coping strategies aimed at managing feelings about a stressor rather than solving it directly, like talking to a friend for comfort, are called:`, ch:[`Problem-focused coping`,`Emotion-focused coping`,`Operant conditioning`,`Sensory adaptation`], ans:1, exp:`Emotion-focused coping helps manage the emotional reaction to stress rather than fixing the stressful situation itself.` },
      { q:`Which of the following is generally considered a healthy way to cope with stress?`, ch:[`Regular exercise and talking to supportive friends or family`,`Avoiding all responsibilities indefinitely`,`Ignoring the stressor completely and hoping it disappears`,`Isolating yourself from everyone`], ans:0, exp:`Exercise and social support are well-supported, healthy strategies for managing and reducing stress.` },
      { q:`Chronic, long-term stress that is never resolved can negatively affect:`, ch:[`Only a person's mood, with no physical effects`,`Both physical health and mental well-being`,`Only academic performance`,`Nothing, since stress has no lasting effects`], ans:1, exp:`Ongoing, unmanaged stress can harm both physical health, such as the immune system, and mental well-being.` },
      { q:`A stressor that is mild and predictable, like a pop quiz you expected, is generally:`, ch:[`Always more harmful than major life events`,`Usually easier to cope with than major, unpredictable life changes`,`Impossible to cope with`,`The same as chronic stress`], ans:1, exp:`Mild, predictable stressors are usually easier to manage than sudden, major, or uncontrollable life changes.` },
      { q:`Which of the following is an example of a problem-focused coping strategy for stress about a big exam?`, ch:[`Venting to a friend about feeling nervous`,`Creating a structured study schedule to prepare`,`Watching TV to distract yourself and avoid thinking about it`,`Journaling about how anxious you feel`], ans:1, exp:`Making a study schedule directly addresses the source of stress, which is the hallmark of problem-focused coping.` },
      { q:`Relaxation techniques, such as deep breathing or meditation, help reduce stress mainly by:`, ch:[`Increasing heart rate and muscle tension`,`Activating the body's calming (parasympathetic) response`,`Releasing more cortisol`,`Triggering the fight-or-flight response`], ans:1, exp:`Relaxation techniques activate the parasympathetic nervous system, which helps calm the body after a stress response.` },
      { q:`Social support, such as having friends or family to talk to, is generally linked to:`, ch:[`Increased stress and worse coping`,`Better coping with stress and improved well-being`,`No effect on how people handle stress`,`Only helping with physical, not emotional, stress`], ans:1, exp:`Having supportive relationships is strongly linked to better stress management and overall well-being.` },
    ]
  },
  { id:'hb11', cat:'Behavioral & Social Sciences', title:`Social Psychology: Groups & Conformity`, diff:'Easy', qs:[
      { q:`Conformity refers to:`, ch:[`Refusing to follow any social rules`,`Changing your behavior or beliefs to match those of a group`,`Leading a group toward a new decision`,`Avoiding all group activities`], ans:1, exp:`Conformity means adjusting your own behavior or opinions to match the norms or expectations of a group.` },
      { q:`In Solomon Asch's classic line-judging experiments, participants often conformed to a group's obviously wrong answer mainly because of:`, ch:[`A desire to avoid seeming different from the group`,`Being physically forced to agree`,`Not understanding the task`,`Being rewarded with money for agreeing`], ans:0, exp:`Many participants conformed to fit in and avoid standing out, even when they knew the group's answer was wrong.` },
      { q:`Conforming because you genuinely believe the group has more accurate information than you do is called:`, ch:[`Normative social influence`,`Informational social influence`,`Groupthink`,`Deindividuation`], ans:1, exp:`Informational social influence happens when we conform because we believe others' judgments are more likely to be correct.` },
      { q:`Conforming mainly to fit in and be liked by a group, even if you privately disagree, is called:`, ch:[`Informational social influence`,`Normative social influence`,`Self-actualization`,`Extinction`], ans:1, exp:`Normative social influence involves going along with the group to gain approval or avoid rejection, even without believing the group is right.` },
      { q:`In Stanley Milgram's obedience experiments, participants were asked to:`, ch:[`Rate the attractiveness of strangers`,`Deliver what they believed were increasing electric shocks to another person when instructed by an authority figure`,`Solve difficult math problems in a group`,`Memorize long lists of words`], ans:1, exp:`Milgram's study examined how far people would obey an authority figure's instructions to shock another person, even when it seemed harmful.` },
      { q:`Milgram's obedience study is often cited as evidence that:`, ch:[`People never obey authority figures`,`Ordinary people can follow harmful orders from an authority figure under certain conditions`,`Only cruel people would ever administer shocks`,`Obedience depends entirely on personality, not situation`], ans:1, exp:`The study showed that situational factors, like the presence of an authority figure, can lead many ordinary people to follow harmful instructions.` },
      { q:`Groupthink refers to a situation in which:`, ch:[`A group makes better decisions because members share diverse opinions`,`A group's desire for harmony and agreement leads to poor decision-making by avoiding critical thinking`,`Individuals in a group always disagree loudly`,`Group members ignore each other completely`], ans:1, exp:`Groupthink occurs when a group values agreement so much that members avoid raising concerns, leading to poor decisions.` },
      { q:`The bystander effect describes the finding that a person is:`, ch:[`More likely to help someone in an emergency when more bystanders are present`,`Less likely to help someone in an emergency when more bystanders are present`,`Equally likely to help regardless of how many bystanders are present`,`Always likely to help immediately, no matter the situation`], ans:1, exp:`Research shows people are often less likely to help in an emergency when other bystanders are present, partly because responsibility feels shared.` },
      { q:`Social loafing refers to the tendency for people to:`, ch:[`Work harder when part of a group than when working alone`,`Put in less individual effort when working in a group than when working alone`,`Refuse to participate in any group activity`,`Always outperform others when in a group`], ans:1, exp:`Social loafing happens when people exert less effort on a group task, often because individual contributions are less noticeable.` },
      { q:`A "group norm" refers to:`, ch:[`A formal written law`,`An unwritten shared expectation about how members of a group should behave`,`A punishment for breaking a rule`,`A type of memory test`], ans:1, exp:`Group norms are the informal, shared rules or expectations that guide how members of a group are expected to act.` },
      { q:`Which factor was shown to reduce conformity in Asch's experiments?`, ch:[`Having at least one other person also give the correct, different answer`,`Increasing the group size to twenty people`,`Removing all group members except the participant`,`Making the correct answer harder to see`], ans:0, exp:`When even one other person broke from the group's incorrect answer, conformity dropped sharply because the participant no longer felt alone.` },
      { q:`Which of these is the best real-world example of conformity?`, ch:[`A student wears a school uniform because it's required by school policy`,`A teenager starts using new slang because all of their friends use it`,`A person eats lunch because they are hungry`,`A driver stops at a red light to avoid an accident`], ans:1, exp:`Adopting new slang to match friends reflects conformity, since the behavior changes to match the group rather than for a personal or safety reason.` },
    ]
  },
  { id:'hb12', cat:'Behavioral & Social Sciences', title:`Social Psychology: Attitudes & Persuasion Basics`, diff:'Easy', qs:[
      { q:`In psychology, an attitude is best defined as:`, ch:[`A person's height and weight`,`A learned tendency to evaluate something in a positive or negative way`,`A type of memory storage`,`A physical reflex`], ans:1, exp:`An attitude is a relatively stable way of thinking or feeling positively or negatively about a person, idea, or object.` },
      { q:`Persuasion refers to:`, ch:[`Forcing someone to change their behavior through threats`,`The process of trying to change someone's attitude or behavior through communication`,`A type of memory loss`,`An involuntary reflex response`], ans:1, exp:`Persuasion is the deliberate attempt to influence another person's beliefs, attitudes, or actions through communication.` },
      { q:`A persuasive message delivered by a messenger who is seen as trustworthy and knowledgeable is generally:`, ch:[`Less effective than one from an untrustworthy source`,`More effective because credibility increases persuasion`,`Completely ignored by audiences`,`Only effective if the message is very short`], ans:1, exp:`Messages from credible, trustworthy sources tend to be more persuasive than the same message from an untrustworthy source.` },
      { q:`Cognitive dissonance, first described by Leon Festinger, refers to:`, ch:[`The comfortable feeling of holding consistent beliefs`,`The uncomfortable feeling that occurs when a person holds two conflicting beliefs or when behavior conflicts with beliefs`,`A memory storage technique`,`A stage of sleep`], ans:1, exp:`Cognitive dissonance is the mental discomfort felt when our actions and beliefs don't match, which often motivates us to change one of them.` },
      { q:`A smoker who knows smoking is unhealthy but keeps smoking might reduce their discomfort by telling themselves "it's not that bad" or "I'll quit later." This is an example of reducing:`, ch:[`Cognitive dissonance`,`Social loafing`,`Groupthink`,`The bystander effect`], ans:0, exp:`Changing a belief to better match a behavior (or vice versa) is a common way people reduce cognitive dissonance.` },
      { q:`Advertisements that repeatedly pair a product with likable, attractive people are relying mainly on which learning principle to shape attitudes?`, ch:[`Operant conditioning`,`Classical conditioning`,`Cognitive dissonance`,`Social loafing`], ans:1, exp:`Repeatedly pairing a neutral product with positive images can create a positive attitude toward the product through classical conditioning.` },
      { q:`The "foot-in-the-door" persuasion technique involves:`, ch:[`Making a large request first, then a smaller one`,`Getting someone to agree to a small request first, making them more likely to agree to a larger request later`,`Refusing to make any request at all`,`Threatening someone until they comply`], ans:1, exp:`The foot-in-the-door technique starts with a small, easy request to increase the chance a person will later agree to a bigger one.` },
      { q:`The "door-in-the-face" persuasion technique involves:`, ch:[`Starting with a large request that will likely be refused, then following with a smaller, more reasonable request`,`Only ever making one small request`,`Slamming a literal door in someone's face`,`Ignoring the other person's response entirely`], ans:0, exp:`This technique starts big and expects a "no," making the smaller follow-up request seem more reasonable by comparison.` },
      { q:`Persuasive messages that rely on careful, logical arguments and evidence are using what researchers call the:`, ch:[`Peripheral route to persuasion`,`Central route to persuasion`,`Bystander route`,`Conformity route`], ans:1, exp:`The central route to persuasion involves thoughtful consideration of logical arguments and evidence.` },
      { q:`Persuasive messages that rely on superficial cues, like an attractive spokesperson or catchy music, are using what researchers call the:`, ch:[`Central route to persuasion`,`Peripheral route to persuasion`,`Informational route`,`Normative route`], ans:1, exp:`The peripheral route relies on surface-level cues rather than careful reasoning about the actual message content.` },
      { q:`Mere exposure effect refers to the finding that:`, ch:[`People tend to develop more positive feelings toward things they are repeatedly exposed to`,`Repeated exposure to something always creates negative feelings`,`Exposure to a stimulus has no effect on attitudes`,`People only like things they have never seen before`], ans:0, exp:`The mere exposure effect shows that simply seeing something repeatedly can increase our liking for it, even without any other interaction.` },
      { q:`Which of the following best illustrates an attitude, as psychologists define the term?`, ch:[`A student's height`,`A student's generally positive feelings about recycling`,`A student's blood type`,`A student's reaction time on a test`], ans:1, exp:`Having positive or negative feelings about something, like recycling, is a classic example of an attitude.` },
    ]
  },
  { id:'hb13', cat:'Behavioral & Social Sciences', title:`Intro to Psychological Disorders`, diff:'Easy', qs:[
      { q:`In psychology, a psychological disorder is generally described as a pattern of thoughts, feelings, or behaviors that is:`, ch:[`Slightly unusual but never distressing`,`Distressing or impairing and different from what is typically expected in a person's culture`,`Always caused by a single, known event`,`Only diagnosed in adults`], ans:1, exp:`Psychological disorders typically involve significant distress or difficulty functioning that goes beyond what's typical in a person's cultural context.` },
      { q:`Anxiety disorders are generally characterized by:`, ch:[`Excessive and persistent worry or fear that interferes with daily life`,`A complete lack of any emotion`,`Only physical injuries`,`Improved memory and focus`], ans:0, exp:`Anxiety disorders involve ongoing, excessive worry or fear that goes beyond normal everyday nervousness and disrupts daily functioning.` },
      { q:`Major depressive disorder is generally characterized by:`, ch:[`Persistent sadness or loss of interest in activities, lasting for an extended period of time`,`A brief moment of sadness that passes within minutes`,`Constant high energy and euphoria`,`Improved sleep and appetite`], ans:0, exp:`Depression involves ongoing feelings of sadness or lost interest in things a person once enjoyed, lasting for weeks or longer, not just brief sadness.` },
      { q:`Which of the following best distinguishes a normal, everyday fear (like nervousness before a test) from an anxiety disorder?`, ch:[`Whether the fear is ever felt at all`,`The intensity, duration, and degree to which it interferes with daily functioning`,`Whether the person ever smiles`,`Whether the person is a teenager or adult`], ans:1, exp:`Everyday nervousness becomes a disorder when it becomes especially intense, long-lasting, and disruptive to daily life.` },
      { q:`A phobia is best described as:`, ch:[`A mild preference for one activity over another`,`An intense, irrational fear of a specific object or situation`,`A type of memory disorder`,`A normal and brief startle reflex`], ans:1, exp:`A phobia is a strong, often irrational fear of a specific thing or situation that leads to avoidance and distress.` },
      { q:`Bipolar disorder is generally characterized by:`, ch:[`Alternating episodes of depression and mania (unusually high energy and mood)`,`Constant, unchanging sadness with no other symptoms`,`Only physical symptoms, with no effect on mood`,`Improved memory during depressive episodes`], ans:0, exp:`Bipolar disorder involves shifts between depressive episodes and manic episodes of unusually elevated mood and energy.` },
      { q:`Which of the following is generally considered a myth about mental illness that most psychologists reject?`, ch:[`Mental illnesses are common and treatable`,`People with mental illness are always dangerous or violent`,`Many mental disorders have both biological and environmental contributing factors`,`Treatment, such as therapy, can help many people manage symptoms`], ans:1, exp:`Most people with mental illness are not violent; this is a harmful stereotype not supported by research.` },
      { q:`Psychotherapy, in general, refers to:`, ch:[`Only prescribing medication`,`Talking-based treatment approaches used to help people understand and manage psychological difficulties`,`A type of brain surgery`,`A method used only to diagnose physical illnesses`], ans:1, exp:`Psychotherapy involves trained professionals using structured conversation and techniques to help people cope with psychological difficulties.` },
      { q:`Which of these professionals is medically trained and licensed to prescribe medication for psychological disorders?`, ch:[`A school counselor`,`A psychiatrist`,`A social worker`,`A life coach`], ans:1, exp:`Psychiatrists are medical doctors who can diagnose mental disorders and prescribe medication, unlike most other mental health professionals.` },
      { q:`Obsessive-compulsive disorder (OCD) generally involves:`, ch:[`Unwanted, intrusive thoughts (obsessions) and repetitive behaviors performed to reduce anxiety (compulsions)`,`Only physical symptoms with no thoughts involved`,`A complete loss of memory`,`Unusually high self-confidence`], ans:0, exp:`OCD involves distressing, repeated thoughts along with repetitive actions a person feels driven to perform to ease that distress.` },
      { q:`Which statement reflects an accurate and respectful understanding of psychological disorders?`, ch:[`People can simply "snap out of" a mental disorder if they try hard enough`,`Mental disorders are a sign of personal weakness or poor character`,`Mental disorders are real health conditions that can often be effectively treated`,`Only people with severe disorders deserve treatment`], ans:2, exp:`Mental disorders are recognized as genuine health conditions, and effective treatments such as therapy and medication exist for many of them.` },
      { q:`Which of the following would generally be considered a warning sign that professional help may be needed?`, ch:[`Feeling nervous once before a big presentation`,`Ongoing sadness, hopelessness, or anxiety that lasts for weeks and interferes with daily life`,`Feeling tired after a busy week`,`Occasionally disagreeing with a friend`], ans:1, exp:`Persistent, intense symptoms that disrupt daily life for an extended period are a key sign that professional support could help.` },
    ]
  },
  { id:'hb14', cat:'Behavioral & Social Sciences', title:`Intelligence & Testing Basics`, diff:'Easy', qs:[
      { q:`Intelligence, broadly defined by many psychologists, refers to a person's ability to:`, ch:[`Only memorize facts`,`Learn from experience, solve problems, and adapt to new situations`,`Run fast and stay physically fit`,`Only perform well on a single test`], ans:1, exp:`Most psychologists define intelligence broadly as the ability to learn, reason, solve problems, and adapt to new situations.` },
      { q:`IQ stands for:`, ch:[`Individual Quotient`,`Intelligence Quotient`,`Instant Query`,`Internal Quality`], ans:1, exp:`IQ stands for Intelligence Quotient, a score meant to represent a person's relative intellectual ability.` },
      { q:`Alfred Binet originally developed early intelligence tests mainly to:`, ch:[`Identify students who might need extra educational support`,`Rank the general population from smartest to least smart`,`Diagnose physical illnesses`,`Measure personality traits`], ans:0, exp:`Binet created his test to identify French schoolchildren who might benefit from additional academic assistance.` },
      { q:`Howard Gardner's theory of multiple intelligences suggests that:`, ch:[`Intelligence is a single, fixed number`,`There are several distinct types of intelligence, such as musical, spatial, and interpersonal intelligence`,`Only mathematical ability counts as true intelligence`,`Intelligence cannot be measured in any way`], ans:1, exp:`Gardner proposed that people can be intelligent in different ways, not just through traditional academic or logical skills.` },
      { q:`Which of the following is an example of Gardner's "interpersonal intelligence"?`, ch:[`Being skilled at solving complex math equations`,`Being skilled at understanding and relating well to other people`,`Being skilled at recognizing musical patterns`,`Being skilled at physical coordination and movement`], ans:1, exp:`Interpersonal intelligence involves understanding others' emotions, motivations, and social cues effectively.` },
      { q:`A good psychological test is generally expected to be both:`, ch:[`Long and difficult`,`Reliable (consistent results) and valid (measures what it claims to measure)`,`Free of any standardization`,`Impossible to score`], ans:1, exp:`Reliability means a test gives consistent results, and validity means it actually measures what it's designed to measure.` },
      { q:`If an IQ test gives very different scores for the same person when taken on two different days under similar conditions, the test likely has a problem with:`, ch:[`Validity`,`Reliability`,`Standardization`,`Norming`], ans:1, exp:`Reliability refers to consistency; a test that produces very different results each time has low reliability.` },
      { q:`If a test designed to measure math ability actually measures reading speed instead, the test likely has a problem with:`, ch:[`Reliability`,`Validity`,`Norming`,`Standardization`], ans:1, exp:`Validity refers to whether a test truly measures what it claims to measure; this test fails to accurately assess math ability.` },
      { q:`On most standard IQ tests, the average score in the general population is set at approximately:`, ch:[`50`,`75`,`100`,`150`], ans:2, exp:`Most modern IQ tests are designed so that the average score in the general population is set at 100.` },
      { q:`Which of the following is a common criticism of traditional intelligence tests?`, ch:[`They may not fully account for cultural background and life experiences`,`They are always perfectly fair to every test-taker`,`They measure every possible type of ability equally well`,`They have no impact on educational decisions`], ans:0, exp:`A common criticism is that some test questions may unintentionally favor people from certain cultural or educational backgrounds.` },
      { q:`Emotional intelligence generally refers to a person's ability to:`, ch:[`Solve advanced calculus problems`,`Recognize, understand, and manage their own and others' emotions`,`Memorize long lists quickly`,`Run tests in a laboratory`], ans:1, exp:`Emotional intelligence involves being aware of and skillfully managing emotions, both your own and those of others.` },
      { q:`Standardized testing means that a test is:`, ch:[`Given and scored in a consistent way for all test-takers`,`Different for every single person who takes it`,`Never timed`,`Only available to certain groups of people`], ans:0, exp:`Standardization ensures that everyone takes the test under the same conditions and it is scored using the same consistent method.` },
    ]
  },
  { id:'hb15', cat:'Behavioral & Social Sciences', title:`Research Methods in Psychology Basics`, diff:'Easy', qs:[
      { q:`A hypothesis in psychological research is best described as:`, ch:[`A proven fact`,`A testable prediction about the relationship between two or more variables`,`A completed research study`,`A type of survey question`], ans:1, exp:`A hypothesis is an educated, testable guess about how variables might be related, which researchers then test through study.` },
      { q:`In an experiment, the variable that researchers deliberately change or manipulate is called the:`, ch:[`Dependent variable`,`Independent variable`,`Control variable`,`Confounding variable`], ans:1, exp:`The independent variable is the factor a researcher intentionally changes to see its effect on another variable.` },
      { q:`In an experiment, the variable that is measured to see if it was affected by the manipulation is called the:`, ch:[`Independent variable`,`Dependent variable`,`Extraneous variable`,`Placebo variable`], ans:1, exp:`The dependent variable is what researchers measure, expecting it may change because of the independent variable.` },
      { q:`In a well-designed experiment, participants are typically randomly assigned to groups mainly to:`, ch:[`Make the study take longer`,`Ensure the groups are roughly similar at the start, so differences in results can be attributed to the treatment`,`Guarantee everyone gets the same treatment`,`Avoid needing a control group`], ans:1, exp:`Random assignment helps make sure that, on average, the groups are similar at the outset, so any later differences are more likely due to the treatment.` },
      { q:`A control group in an experiment is a group that:`, ch:[`Receives the treatment being tested`,`Does not receive the treatment, so it can be compared to the group that does`,`Is always larger than the experimental group`,`Is never included in real experiments`], ans:1, exp:`The control group does not receive the experimental treatment, providing a baseline for comparison with the treatment group.` },
      { q:`A major strength of experiments compared to other research methods is that they can help establish:`, ch:[`Correlation only`,`Cause and effect relationships`,`Personal opinions`,`Population averages only`], ans:1, exp:`Because researchers control variables and randomly assign participants, well-designed experiments can show cause and effect.` },
      { q:`A correlation describes:`, ch:[`A cause-and-effect relationship between two variables`,`A relationship in which two variables tend to change together, without proving one causes the other`,`A type of memory test`,`A stage of sleep`], ans:1, exp:`Correlation shows that two variables are related or tend to move together, but it does not by itself prove that one causes the other.` },
      { q:`The phrase "correlation does not imply causation" means that:`, ch:[`Two related variables always cause each other`,`Just because two variables are related doesn't mean one variable causes changes in the other`,`Correlations are never useful in research`,`Only experiments can show any relationship between variables`], ans:1, exp:`Even when two variables are strongly related, some other factor might explain the connection, so a correlation alone doesn't prove causation.` },
      { q:`Which of the following is an example of a naturalistic observation study?`, ch:[`Watching and recording children's play behavior on a playground without interfering`,`Giving participants a survey about their play preferences`,`Randomly assigning children to different play activities in a lab`,`Interviewing parents about their children's behavior`], ans:0, exp:`Naturalistic observation involves watching behavior in its real-world setting without the researcher interfering.` },
      { q:`A key limitation of using only self-report surveys in psychological research is that:`, ch:[`They always require expensive equipment`,`Participants may not answer honestly or accurately remember their own behavior`,`They can never be used to study large groups of people`,`They always take years to complete`], ans:1, exp:`Surveys rely on people's honesty and memory, which can sometimes lead to inaccurate or biased responses.` },
      { q:`A case study in psychology involves:`, ch:[`Surveying thousands of people briefly`,`An in-depth investigation of a single individual or small group`,`Randomly assigning many participants to treatment groups`,`Only studying animals, never humans`], ans:1, exp:`A case study is a detailed, in-depth look at one person or a small group, often used to explore rare or unique situations.` },
      { q:`Which research method would be best suited to determine whether a new study technique actually causes improved test scores?`, ch:[`A correlational survey`,`A controlled experiment with random assignment`,`A single case study`,`Naturalistic observation only`], ans:1, exp:`A controlled experiment with random assignment is the best method for establishing cause and effect, such as whether a technique truly improves scores.` },
    ]
  },
];
